class Solution {
    public int scheduleCourse(int[][] courses){
        Arrays.sort(courses,Comparator.comparingInt(course->course[1]));
        PriorityQueue<Integer> durations=new PriorityQueue<>(Comparator.reverseOrder());
        int total=0;
        for(int[] course:courses){
            total+=course[0];
            durations.offer(course[0]);
            if(total>course[1])total-=durations.poll();
        }
        return durations.size();
    }
}

code.kotlin:
class Solution {
    fun scheduleCourse(courses:Array<IntArray>):Int{
        courses.sortBy{
            it[1]
        };
        val durations=java.util.PriorityQueue<Int>(compareByDescending{
            it
        });
        var total=0;
        for(course in courses){
            total+=course[0];
            durations.add(course[0]);
            if(total>course[1])total-=durations.remove()
        };
        return durations.size
    }
}

